/// INI text as Xshell writes it: UTF-16LE with BOM (observed in all bundled .scs files) or plain UTF-8/ASCII (observed in .tkm), CRLF lines.
public enum IniEncoding: Equatable, Sendable { case utf16LittleEndianBOM, utf8 }

public struct IniSection: Equatable, Sendable {
    public var name: String
    public var entries: [(key: String, value: String)]
    public init(name: String, entries: [(key: String, value: String)]) { self.name = name; self.entries = entries }
    public func value(_ key: String) -> String? { entries.first { $0.key.caseInsensitiveCompare(key) == .orderedSame }?.value }
    public static func == (a: IniSection, b: IniSection) -> Bool {
        a.name == b.name && a.entries.map { [$0.key, $0.value] } == b.entries.map { [$0.key, $0.value] }
    }
}

public enum XshellFormatError: Error, Equatable {
    case undecodableText
    case missingSection(String)
    case missingKey(String)
    case invalidColor(key: String, value: String)
    case invalidCaretSequence(String)
}

public enum IniText {
    public static func decode(_ data: Data) throws -> (String, IniEncoding) {
        if data.starts(with: [0xFF, 0xFE]) {
            guard let s = String(data: data.dropFirst(2), encoding: .utf16LittleEndian) else { throw XshellFormatError.undecodableText }
            return (s, .utf16LittleEndianBOM)
        }
        let body = data.starts(with: [0xEF, 0xBB, 0xBF]) ? data.dropFirst(3) : data[...]
        guard let s = String(data: body, encoding: .utf8) else { throw XshellFormatError.undecodableText }
        return (s, .utf8)
    }

    public static func parse(_ text: String) -> [IniSection] {
        var sections: [IniSection] = []
        for raw in text.split(whereSeparator: { $0 == "\n" || $0 == "\r\n" }) {
            let line = raw.trimmingCharacters(in: CharacterSet(charactersIn: "\r"))
            if line.isEmpty || line.hasPrefix(";") { continue }
            if line.hasPrefix("["), line.hasSuffix("]") {
                sections.append(IniSection(name: String(line.dropFirst().dropLast()), entries: []))
            } else if let eq = line.firstIndex(of: "="), !sections.isEmpty {
                sections[sections.count - 1].entries.append((String(line[..<eq]), String(line[line.index(after: eq)...])))
            }
        }
        return sections
    }

    public static func encode(_ sections: [IniSection], _ encoding: IniEncoding) -> Data {
        var text = ""
        for s in sections {
            text += "[\(s.name)]\r\n"
            for e in s.entries { text += "\(e.key)=\(e.value)\r\n" }
        }
        switch encoding {
        case .utf8: return Data(text.utf8)
        case .utf16LittleEndianBOM: return Data([0xFF, 0xFE]) + text.data(using: .utf16LittleEndian)!
        }
    }
}

public struct RGB: Equatable, Hashable, Sendable {
    public var red: UInt8, green: UInt8, blue: UInt8
    public init(red: UInt8, green: UInt8, blue: UInt8) { self.red = red; self.green = green; self.blue = blue }
    /// Xshell stores colors as six lowercase hex digits in RRGGBB order.
    public init?(hex: String) {
        guard hex.count == 6, let v = UInt32(hex, radix: 16) else { return nil }
        self.init(red: UInt8(v >> 16 & 0xFF), green: UInt8(v >> 8 & 0xFF), blue: UInt8(v & 0xFF))
    }
    public var hex: String { String(format: "%02x%02x%02x", red, green, blue) }
}

/// One Xshell `.scs` color scheme: a `[Color Scheme]` section with text, bold text, background and the 8 ANSI colors in normal and bold forms.
public struct ColorScheme: Equatable, Sendable {
    public static let sectionName = "Color Scheme"
    public static let ansiNames = ["black", "red", "green", "yellow", "blue", "magenta", "cyan", "white"]

    /// Xshell uses the file name (without `.scs`) as the scheme name; the file itself has no name key.
    public var name: String
    public var text: RGB
    public var boldText: RGB
    public var background: RGB
    /// ANSI colors 0–7 in `ansiNames` order.
    public var normal: [RGB]
    /// Bold (bright) ANSI colors 0–7.
    public var bold: [RGB]
    /// Keys outside the known set, kept so a rewrite does not drop them.
    public var extra: [(key: String, value: String)] = []
    public var encoding: IniEncoding = .utf16LittleEndianBOM
    /// Key order as read; Xshell does not write keys in a fixed order, so a rewrite keeps the original order.
    public var keyOrder: [String] = []

    public static func == (a: ColorScheme, b: ColorScheme) -> Bool {
        a.name == b.name && a.text == b.text && a.boldText == b.boldText && a.background == b.background
            && a.normal == b.normal && a.bold == b.bold && a.extra.map { [$0.key, $0.value] } == b.extra.map { [$0.key, $0.value] }
    }

    public init(name: String, text: RGB, boldText: RGB, background: RGB, normal: [RGB], bold: [RGB]) {
        precondition(normal.count == 8 && bold.count == 8)
        self.name = name; self.text = text; self.boldText = boldText; self.background = background; self.normal = normal; self.bold = bold
    }

    public init(data: Data, name: String) throws {
        let (text, encoding) = try IniText.decode(data)
        guard let section = IniText.parse(text).first(where: { $0.name == Self.sectionName }) else { throw XshellFormatError.missingSection(Self.sectionName) }
        func color(_ key: String) throws -> RGB {
            guard let v = section.value(key) else { throw XshellFormatError.missingKey(key) }
            guard let c = RGB(hex: v) else { throw XshellFormatError.invalidColor(key: key, value: v) }
            return c
        }
        self.name = name
        self.text = try color("text")
        self.boldText = try color("text(bold)")
        self.background = try color("background")
        self.normal = try Self.ansiNames.map { try color($0) }
        self.bold = try Self.ansiNames.map { try color("\($0)(bold)") }
        let known = Set(["text", "text(bold)", "background"] + Self.ansiNames + Self.ansiNames.map { "\($0)(bold)" })
        self.extra = section.entries.filter { !known.contains($0.key.lowercased()) }
        self.encoding = encoding
        self.keyOrder = section.entries.map(\.key)
    }

    public init(contentsOf url: URL) throws {
        try self.init(data: Data(contentsOf: url), name: url.deletingPathExtension().lastPathComponent)
    }

    /// Writes the scheme back in Xshell's layout (UTF-16LE with BOM by default). Key order follows the known set, then extras.
    public func encoded() -> Data {
        var entries: [(key: String, value: String)] = [("text", text.hex), ("text(bold)", boldText.hex), ("background", background.hex)]
        for (i, n) in Self.ansiNames.enumerated() { entries.append((n, normal[i].hex)); entries.append(("\(n)(bold)", bold[i].hex)) }
        let all = entries + extra
        var ordered: [(key: String, value: String)] = keyOrder.compactMap { k in all.first { $0.key.lowercased() == k.lowercased() }.map { (k, $0.value) } }
        ordered += all.filter { e in !keyOrder.contains { $0.lowercased() == e.key.lowercased() } }
        return IniText.encode([IniSection(name: Self.sectionName, entries: ordered)], encoding)
    }

    /// 16-entry ANSI palette (normal 0–7, then bold 8–15), the order terminal emulators commonly use.
    public var ansiPalette: [RGB] { normal + bold }
}

/// One `[FUNCKEY]` entry of an Xshell `.tkm` terminal key map.
public struct FunctionKeyBinding: Equatable, Sendable {
    public enum Output: Equatable, Sendable {
        /// Bytes to send, written in caret notation (`^[` is ESC).
        case sequence([UInt8])
        /// A value without caret notation, such as `F11` or `Shift+F1` in the bundled sample. Its runtime meaning was not observed; it is kept as text.
        case named(String)
    }
    /// Key name as written, for example `F1` or `S_F1` (the `S_` prefix appears beside `Shift+` values in the sample).
    public var key: String
    public var raw: String
    public var output: Output
}

public struct TerminalKeyMap: Equatable, Sendable {
    public static let sectionName = "FUNCKEY"
    public var bindings: [FunctionKeyBinding]
    public var encoding: IniEncoding

    public init(data: Data) throws {
        let (text, encoding) = try IniText.decode(data)
        guard let section = IniText.parse(text).first(where: { $0.name.uppercased() == Self.sectionName }) else { throw XshellFormatError.missingSection(Self.sectionName) }
        self.bindings = try section.entries.map { FunctionKeyBinding(key: $0.key, raw: $0.value, output: try Self.output($0.value)) }
        self.encoding = encoding
    }

    public init(contentsOf url: URL) throws { try self.init(data: Data(contentsOf: url)) }

    public func binding(_ key: String) -> FunctionKeyBinding? { bindings.first { $0.key.caseInsensitiveCompare(key) == .orderedSame } }

    public func encoded() -> Data {
        IniText.encode([IniSection(name: Self.sectionName, entries: bindings.map { ($0.key, $0.raw) })], encoding)
    }

    /// Caret notation: `^X` is X with bit 0x40 cleared (`^[` = 0x1B, `^A` = 0x01, `^?` = 0x7F). A value with no `^` is treated as a name.
    static func output(_ value: String) throws -> FunctionKeyBinding.Output {
        guard value.contains("^") else { return .named(value) }
        var bytes: [UInt8] = []
        var it = Array(value.utf8).makeIterator()
        while let b = it.next() {
            if b == UInt8(ascii: "^") {
                guard let c = it.next() else { throw XshellFormatError.invalidCaretSequence(value) }
                if c == UInt8(ascii: "?") { bytes.append(0x7F) }
                else if (0x40...0x5F).contains(c) || (0x61...0x7A).contains(c) { bytes.append((c & 0x5F) ^ 0x40) }
                else { throw XshellFormatError.invalidCaretSequence(value) }
            } else { bytes.append(b) }
        }
        return .sequence(bytes)
    }
}

// Feature entry: payload is JSON {"kind": "scs"|"tkm", "path": "..."}. An empty payload reports readiness.
public enum FormatsFeature: CarveFeature {
    public static let id = "formats"
    public static let contractSha256 = "5bd8ffb27b6d098e8a8a4351fd0313592fafe61a008d29940a8a9d0dbc3fdc74"
    public static let dependsOn: [String] = []

    public static func run(_ request: FeatureRequest, dependencies: FeatureOutputs) throws -> FeatureResponse {
        if request.payload.isEmpty { return FeatureResponse(payload: #"{"ready":true,"kinds":["scs","tkm"]}"#) }
        guard let obj = try JSONSerialization.jsonObject(with: Data(request.payload.utf8)) as? [String: String],
              let kind = obj["kind"], let path = obj["path"] else { throw FeatureError.failed(id, "expected JSON {kind, path}") }
        let url = URL(fileURLWithPath: path)
        let out: [String: Any]
        switch kind {
        case "scs":
            let s = try ColorScheme(contentsOf: url)
            out = ["name": s.name, "text": s.text.hex, "boldText": s.boldText.hex, "background": s.background.hex, "palette": s.ansiPalette.map(\.hex)]
        case "tkm":
            let m = try TerminalKeyMap(contentsOf: url)
            out = ["bindings": m.bindings.map { b -> [String: Any] in
                switch b.output {
                case .sequence(let bytes): return ["key": b.key, "bytes": bytes.map(Int.init)]
                case .named(let n): return ["key": b.key, "named": n]
                } }]
        default: throw FeatureError.failed(id, "unknown kind \(kind)")
        }
        return FeatureResponse(payload: String(decoding: try JSONSerialization.data(withJSONObject: out, options: [.sortedKeys]), as: UTF8.self))
    }
}
